import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"span"> {}

<const/{ class: className, content, ...rest }=input/>

<span
  data-slot="marker-content"
  class=cn("group-data-[variant=separator]/marker:flex-none group-data-[variant=separator]/marker:text-center *:[a]:hover:text-foreground *:[a]:underline *:[a]:underline-offset-3 min-w-0 wrap-break-word", className)
  ...rest
>
  <${content}/>
</span>

import { markerVariants, type MarkerVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, MarkerVariants {
  /**
   * shadcn's source renders via Radix `Slot.Root` when `asChild` is set, so
   * the marker's own attrs/class merge onto the single child element instead
   * of wrapping it in a `<div>`. Marko has no equivalent runtime slot-merge
   * primitive, so `asChild` is accepted for API parity but is a no-op here:
   * we always render the wrapping `<div>`. Content still renders normally.
   */
  asChild?: boolean;
}

<const/{ variant = "default", class: className, asChild, content, ...rest }=input/>

<div
  data-slot="marker"
  data-variant=variant
  class=cn(markerVariants({ variant, className }))
  ...rest
>
  <${content}/>
</div>

import { cva, type VariantProps } from "class-variance-authority";

export const markerVariants = cva(
  "gap-2 text-xs text-muted-foreground [a]:hover:text-foreground [a]:underline-offset-3 [a]:underline [&_svg:not([class*='size-'])]:size-3.5 min-h-4 text-left group/marker relative flex w-full items-center",
  {
    variants: {
      variant: {
        default: "",
        separator: "before:h-px before:min-w-0 before:flex-1 before:bg-border after:h-px after:min-w-0 after:flex-1 after:bg-border before:mr-1 after:ml-1",
        border: "border-b border-border pb-2",
      },
    },
  },
);

export type MarkerVariants = VariantProps<typeof markerVariants>;
